import CoreGraphics
import Foundation

public enum InterceptedEvent: Equatable, Sendable {
    case interceptScroll(deltaY: Int64, deltaX: Int64)
    case interceptButton(button: Int, isDown: Bool)
    case passThrough
}

public struct EventTapFilter {
    public static let magicUserData: Int64 = 0x4D4D4658 // 'MMFX'

    public static func classify(type: CGEventType, event: CGEvent) -> InterceptedEvent {
        // Pass through synthetic events generated by our engine
        let userData = event.getIntegerValueField(.eventSourceUserData)
        if userData == magicUserData {
            return .passThrough
        }

        switch type {
        case .scrollWheel:
            let isContinuous = event.getIntegerValueField(.scrollWheelEventIsContinuous)
            let momentumPhase = event.getIntegerValueField(.scrollWheelEventMomentumPhase)
            if isContinuous == 0 && momentumPhase == 0 {
                var dy = event.getIntegerValueField(.scrollWheelEventDeltaAxis1)
                var dx = event.getIntegerValueField(.scrollWheelEventDeltaAxis2)
                if dy == 0 {
                    dy = event.getIntegerValueField(.scrollWheelEventPointDeltaAxis1)
                }
                if dx == 0 {
                    dx = event.getIntegerValueField(.scrollWheelEventPointDeltaAxis2)
                }
                return .interceptScroll(deltaY: dy, deltaX: dx)
            }
            return .passThrough

        case .otherMouseDown, .otherMouseUp:
            let buttonNumber = Int(event.getIntegerValueField(.mouseEventButtonNumber))
            // Only intercept middle (2) and extra buttons (3, 4, etc.)
            if buttonNumber >= 2 {
                let isDown = (type == .otherMouseDown)
                return .interceptButton(button: buttonNumber, isDown: isDown)
            }
            return .passThrough

        default:
            return .passThrough
        }
    }
}
